@ft.component
def App() -> ft.Control:
    """应用根组件：声明式路由 + 主题下发。

    ``ThemeProvider`` 必须包在**最外层**：它要写 ``page.theme``，
    放在页面组件里会晚一帧，表现为"切模式闪一下旧配色"。
    """
    return ThemeProvider(build=lambda: ft.Router(
        ROUTES, not_found=NotFoundPage, manage_views=False
    ))

def _configure_page(page: ft.Page) -> None:
    """页面级设置（字体）。**主题不在这里设** —— 交给 ``ThemeProvider``，
    否则会出现"两处都能改主题、谁最后生效说不清"的问题。"""
    if FONT_FILE.exists():
        page.fonts = {"AlibabaPuHuiTi": str(FONT_FILE)}
        theme_state().font_family = "AlibabaPuHuiTi"

@ft.control
class MyControl(ft.Container):
    removable: bool = False

    def init(self):
        self.content = ft.Text(value="test")

    def delete(self, e):

        def traverse_controls(controls, control_to_delete):
            for c in controls:
                if c == control_to_delete:
                    controls.remove(c)
                    return
                if hasattr(c, "controls") and len(c.controls) > 0:
                    traverse_controls(c.controls, control_to_delete)

        if self.removable:
            p = self.page
            traverse_controls(p.controls, self)
            p.update()

    def did_mount(self):
        return super().did_mount()

    def will_unmount(self):
        return super().will_unmount()

import flet as ft


@ft.control
class MyControl(ft.Container):
    removable: bool = False

    def init(self):
        self.content = ft.Text(value="test")

    def delete(self, e):

        def traverse_controls(controls, control_to_delete):
            for c in controls:
                if c == control_to_delete:
                    controls.remove(c)
                    return
                if hasattr(c, "controls") and len(c.controls) > 0:
                    traverse_controls(c.controls, control_to_delete)

        if self.removable:
            p = self.page
            traverse_controls(p.controls, self)
            p.update()

    def did_mount(self):
        return super().did_mount()

    def will_unmount(self):
        return super().will_unmount()


def main(page: ft.Page):
    # 透明效果
    page.bgcolor = ft.Colors.TRANSPARENT
    page.window.bgcolor = ft.Colors.TRANSPARENT
    my_control = MyControl(removable=True)
    my_control.content = ft.Text(value="test")
    my_btn = ft.Button(ft.Text(value="test"), on_click=my_control.delete)
    page.add(ft.Column(controls=[my_control, my_btn]))


if __name__ == "__main__":
    ft.run(main)

